import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import {
  deleteItemFromCartAsync,
  increment,
  incrementAsync,
  selectItems,
  updateCartAsync,
} from '../features/cart/cartSlice';

import { Dialog, DialogPanel, DialogTitle, Transition, TransitionChild } from '@headlessui/react'
import { XMarkIcon } from '@heroicons/react/24/outline'
import { Link, Navigate } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { updateUserAsync } from '../features/user/userSlice';
import { createOrderAsync, selectCurrentOrder } from '../features/order/orderSlice';
import { selectUserInfo } from '../features/user/userSlice';
import { discountedPrice } from '../app/constants';


function CheckoutPage() {

    const dispatch = useDispatch();
    const count = useSelector(selectItems);
    const items=useSelector(selectItems);
    const currentOrder=useSelector(selectCurrentOrder);
    const totalAmount = items.reduce((amount, item) => discountedPrice(item.product) * item.quantity + amount,0);
    const totalItems = items.reduce((total, item) => item.quantity + total, 0);

    const { register, handleSubmit, watch, reset, formState: { errors } } = useForm();

    const user=useSelector(selectUserInfo)

    const [selectedAddress, setSelectedAddress] = useState(null);
    const [paymentMethod, setPaymentMethod] = useState(null);

    const handleQuantity=(e,item)=>{
        dispatch(updateCartAsync({id:item.id, quantity: +e.target.value}))
    }

    const handleDelete=(e,itemId)=>{
        dispatch(deleteItemFromCartAsync(itemId));
    }

    const handleAddress=(e)=>{
        // console.log(user.addresses[e.target.value]);
        setSelectedAddress(user.addresses[e.target.value]);
    }

    const handlePayment=(e)=>{
        console.log(e.target.value);
        setPaymentMethod(e.target.value);
    }

    const handleOrder=(e)=>{
      const order={items:items, totalAmount, totalItems, user:user.id, paymentMethod, selectedAddress, status:'pending'}
      dispatch(createOrderAsync(order));
    }


    return (
        <>
            {items.length==0 && <Navigate to='/' replace={true}></Navigate>}
            {currentOrder && currentOrder.paymentMethod==='cash' && <Navigate to={`/order-success/${currentOrder.id}`} replace={true}></Navigate>}

            {currentOrder && currentOrder.paymentMethod==='card' && <Navigate to={`/stripe-checkout/`} replace={true}></Navigate>}

            <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
                <div className="grid grid-cols-1 gap-x-8 gap-y-10 lg:grid-cols-5 ml-3 mr-3">
                    <div className="lg:col-span-3">
                        <form noValidate 
            onSubmit={handleSubmit((data)=>{
            dispatch(
                updateUserAsync({...user,addresses:[...user.addresses,data]})
            );
            reset();
          })} className="py-4 bg-white rounded-md my-3 mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
                            <div className="space-y-12">
                                <div className="border-b border-gray-900/10 pb-12">
                                <h2 className="text-base font-semibold leading-7 text-gray-900">Personal Information</h2>
                                <p className="mt-1 text-sm leading-6 text-gray-600">Use a permanent address where you can receive mail.</p>

                                <div className="mt-10 grid grid-cols-1 gap-x-6 gap-y-8 sm:grid-cols-6">
                                    <div className="sm:col-span-4">
                                    <label htmlFor="first-name" className="block text-sm font-medium leading-6 text-gray-900">
                                        Full name
                                    </label>
                                    <div className="mt-2">
                                        <input
                                        type="text"
                                        {...register('name',{required:'Full name is required'})}
                                        id="first-name"
                                        autoComplete="given-name"
                                        className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                                        />
                                    </div>
                                    </div>

                                    <div className="sm:col-span-4">
                                    <label htmlFor="email" className="block text-sm font-medium leading-6 text-gray-900">
                                        Email address
                                    </label>
                                    <div className="mt-2">
                                        <input
                                        id="email"
                                        {...register('email',{required:'email is required'})}
                                        type="email"
                                        autoComplete="email"
                                        className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                                        />
                                    </div>
                                    </div>

                                    <div className="sm:col-span-4">
                                    <label htmlFor="country" className="block text-sm font-medium leading-6 text-gray-900">
                                        Phone number
                                    </label>
                                    <div className="mt-2">
                                        <input
                                        id="phone"
                                        {...register('phone',{required:'Phone number is required'})}
                                        type="tel"
                                        autoComplete="phone"
                                        className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                                        />
                                    </div>
                                    </div>

                                    <div className="col-span-full">
                                    <label htmlFor="street-address" className="block text-sm font-medium leading-6 text-gray-900">
                                        Street address
                                    </label>
                                    <div className="mt-2">
                                        <input
                                        type="text"
                                        {...register('street',{required:'Street address is required'})}
                                        id="street"
                                        autoComplete="street-address"
                                        className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                                        />
                                    </div>
                                    </div>

                                    <div className="sm:col-span-2 sm:col-start-1">
                                    <label htmlFor="city" className="block text-sm font-medium leading-6 text-gray-900">
                                        City
                                    </label>
                                    <div className="mt-2">
                                        <input
                                        type="text"
                                        {...register('city',{required:'City name is required'})}
                                        id="city"
                                        autoComplete="address-level2"
                                        className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                                        />
                                    </div>
                                    </div>

                                    <div className="sm:col-span-2">
                                    <label htmlFor="state" className="block text-sm font-medium leading-6 text-gray-900">
                                        State / Province
                                    </label>
                                    <div className="mt-2">
                                        <input
                                        type="text"
                                        {...register('state',{required:'State name is required'})}
                                        id="state"
                                        autoComplete="address-level1"
                                        className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                                        />
                                    </div>
                                    </div>

                                    <div className="sm:col-span-2">
                                    <label htmlFor="pinCode" className="block text-sm font-medium leading-6 text-gray-900">
                                        ZIP / Postal code
                                    </label>
                                    <div className="mt-2">
                                        <input
                                        type="text"
                                        {...register('pinCode',{required:'PIN code is required'})}
                                        id="pinCode"
                                        autoComplete="pinCode"
                                        className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-indigo-600 sm:text-sm sm:leading-6"
                                        />
                                    </div>
                                    </div>
                                </div>
                                <div className="mt-6 flex items-center justify-end gap-x-6">
                                    <button type="button" className="text-sm font-semibold leading-6 text-gray-900">
                                    Reset
                                    </button>
                                    <button
                                    type="submit"
                                    className="rounded-md bg-indigo-600 px-3 py-2 text-sm font-semibold text-white shadow-sm hover:bg-indigo-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600"
                                    >
                                    Add Address
                                    </button>
                                </div>
                                </div>

                                

                                <div className="border-b border-gray-900/10 pb-12">
                                <h2 className="text-base font-semibold leading-7 text-gray-900">Address</h2>
                                <p className="mt-1 text-sm leading-6 text-gray-600">
                                    Choose from existing address
                                </p>
                                <ul role="list" className="divide-y divide-gray-100">
                                {user.addresses.map((address,index) => (
                                    <li key={index} className="flex justify-between gap-x-6 p-5 my-2 border-none bg-slate-200 rounded-xl">
                                    <div className="flex min-w-0 gap-x-4">
                                        <input
                                            name="address"
                                            type="radio"
                                            className="h-4 w-4 border-gray-300 text-indigo-500 focus:ring-transparent"
                                            onChange={(e)=>handleAddress(e)}
                                            value={index}
                                        />
                                        <div className="min-w-0 flex-auto">
                                        <p className="text-sm font-semibold leading-6 text-gray-900">{address.name}</p>
                                        <p className="mt-1 truncate text-xs leading-5 text-gray-600">{address.street}</p>
                                        <p className="mt-1 truncate text-xs leading-5 text-gray-600">{address.city}</p>
                                        <p className="mt-1 truncate text-xs leading-5 text-gray-600">{address.state}</p>
                                    </div>
                                        
                                    </div>
                                    <div className="hidden shrink-0 sm:flex sm:flex-col sm:items-end">
                                        <p className="text-sm leading-6 text-gray-900">Phone: +91-{address.phone}</p>
                                        <p className="text-sm leading-6 text-gray-500">{address.pincode}</p>
                                    </div>
                                    </li>
                                ))}
                                </ul>

                                <div className="mt-10 space-y-10">
                                    <fieldset>
                                    <legend className="text-sm font-semibold leading-6 text-gray-900">Payment methods</legend>
                                    <div className="mt-6 space-y-6">
                                        <div className="flex items-center gap-x-3">
                                        <input
                                            id="cash"
                                            name="payments"
                                            type="radio"
                                            onChange={handlePayment}
                                            value="cash"
                                            checked={paymentMethod==="cash"}
                                            className="h-4 w-4 border-gray-300 text-indigo-600 focus:ring-indigo-600"
                                        />
                                        <label htmlFor="cash" className="block text-sm font-medium leading-6 text-gray-900">
                                            Cash On Delivery
                                        </label>
                                        </div>
                                        <div className="flex items-center gap-x-3">
                                        <input
                                            id="card"
                                            name="payments"
                                            type="radio"
                                            onChange={handlePayment}
                                            value="card"
                                            checked={paymentMethod==="card"}
                                            className="h-4 w-4 border-gray-300 text-indigo-600 focus:ring-indigo-600"
                                        />
                                        <label htmlFor="card" className="block text-sm font-medium leading-6 text-gray-900">
                                            Debit/Credit Card
                                        </label>
                                        </div>
                                    </div>
                                    </fieldset>
                                </div>
                                </div>
                            </div>

                            
                        </form>
                    </div>
                    <div className="lg:col-span-2">
                    <div className="bg-white rounded-md mt-3 mx-auto max-w-7xl px-4 sm:px-6 lg:px-4">
        <h1 className="text-4xl font-semibold tracking-tight text-gray-900 pt-3 pb-3">Cart</h1>
        <div className="border-t border-gray-200 px-4 py-6 sm:px-6">
            <div className="flow-root">
              <ul role="list" className="-my-6 divide-y divide-gray-200">
                {items.map((item) => (
                  <li key={item.id} className="flex py-6">
                    <div className="h-24 w-24 flex-shrink-0 overflow-hidden rounded-md border border-gray-200">
                      <img
                        src={item.product.thumbnail}
                        alt={item.product.title}
                        className="h-full w-full object-cover object-center"
                      />
                    </div>

                    <div className="ml-4 flex flex-1 flex-col">
                      <div>
                        <div className="flex justify-between text-base font-medium text-gray-900">
                          <h3>
                            <a href={item.product.href}>{item.product.title}</a>
                          </h3>
                          <p className="ml-4">${discountedPrice(item.product)}</p>
                        </div>
                        <p className="mt-1 text-sm text-gray-500">{item.product.brand}</p>
                      </div>
                      <div className="flex flex-1 items-end justify-between text-sm">
                        <p className="text-gray-500">Quantity 
                          <select onChange={(e)=>handleQuantity(e,item)} value={item.quantity} className="ml-3 rounded-lg bg-zinc-200 border-none">
                            <option value="1">1</option>
                            <option value="2">2</option>
                            <option value="3">3</option>
                            <option value="4">4</option>
                          </select>
                        </p>
                        <div className="flex">
                          <button
                            type="button"
                            className="font-medium text-indigo-600 hover:text-indigo-500"
                            onClick={(e)=>handleDelete(e,item.id)}
                          >
                            Remove
                          </button>
                        </div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          </div>

        <div className="border-t border-gray-200 px-4 py-6 sm:px-6">
          <div className="flex justify-between text-base font-medium text-gray-900">
            <p>Subtotal</p>
            <p>${totalAmount.toFixed(2)}</p>
          </div>
          <div className="flex justify-between text-base font-medium text-gray-900">
            <p>Total Items</p>
            <p>{totalItems} items</p>
          </div>
          <p className="mt-0.5 text-sm text-gray-500">Shipping and taxes calculated at checkout.</p>
          <div className="mt-6">
            <div
              onClick={handleOrder}
              className="cursor-pointer flex items-center justify-center rounded-md border border-transparent bg-indigo-600 px-6 py-3 text-base font-medium text-white shadow-sm hover:bg-indigo-700"
            >
              Order Now
            </div>
          </div>
          <div className="mt-6 flex justify-center text-center text-sm text-gray-500">
            <p>
              or{' '}
              <Link to="/">
                <button
                  type="button"
                  className="font-medium text-indigo-600 hover:text-indigo-500"
                //   onClick={() => setOpen(false)}
                >
                  Continue Shopping
                  <span aria-hidden="true"> &rarr;</span>
                </button>
              </Link>
            </p>
          </div>
        </div>
      </div>
                    </div>
                </div>
            </div>
        </> 
    );
}

export default CheckoutPage;