import React, { useState,Fragment, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { ChevronLeftIcon, ChevronRightIcon, StarIcon } from '@heroicons/react/20/solid'
import { Link } from 'react-router-dom';
import { XMarkIcon } from '@heroicons/react/24/outline'
import { ChevronDownIcon, FunnelIcon, MinusIcon, PlusIcon, Squares2X2Icon } from '@heroicons/react/20/solid'
import {discountedPrice, ITEMS_PER_PAGE} from '../../../app/constants.js';

import {
  Dialog,
  DialogPanel,
  Disclosure,
  DisclosureButton,
  DisclosurePanel,
  Menu,
  MenuButton,
  MenuItem,
  MenuItems,
  Transition,
  TransitionChild,
} from '@headlessui/react'

import {
  fetchAllProductsAsync,
  selectAllProducts,
  selectAllBrands,
  selectAllCategories,
  selectTotalItems,
  fetchProductsByFilterAsync,
  fetchAllBrandsAsync,
  fetchAllCategoriesAsync
} from '../../product/ProductSlice.js';

const sortOptions = [
  { name: 'Best Rating', sort:'rating', order:'desc', current: false },
  { name: 'Price: Low to High', sort:'price', order:'asc', current: false },
  { name: 'Price: High to Low', sort:'price', order:'desc', current: false },
]

function classNames(...classes) {
  return classes.filter(Boolean).join(' ')
}

export default function AdminProductList() {
  const dispatch = useDispatch();
  const products=useSelector(selectAllProducts)
  const brands=useSelector(selectAllBrands)
  const categories=useSelector(selectAllCategories)
  const totalItems=useSelector(selectTotalItems)
  const [filter, setfilter] = useState({});
  const [sort, setsort] = useState({});
  const [page, setpage] = useState(1);
  const [mobileFiltersOpen, setMobileFiltersOpen] = useState(false);

  const filters = [
    {
      id: 'brand',
      name: 'Brand',
      options: brands,
    },
    {
      id: 'category',
      name: 'Category',
      options: categories,
    },
  ]
  
  const handleFilter=(e,section,option)=>{
    let newFilter={...filter};
    if(e.target.checked)
    {
      if(newFilter[section.id])
      {
        newFilter[section.id].push(option.value); 
      }
      else
      {
        newFilter[section.id]=[option.value];
      }
    }
    else
    {
      const index=newFilter[section.id].findIndex(e=>e===option.value); 
      newFilter[section.id].splice(index,1);
    }
    
    // console.log({newFilter})
    setfilter(newFilter);
  }

  const handleSort=(e,option)=>{
    let sort={_sort:option.sort,_order:option.order};
    setsort(sort);
  }

  const handlePage=(page)=>{
    // console.log({page})
    setpage(page);
  }

  useEffect(()=>{
    const pagination={_page:page, _limit:ITEMS_PER_PAGE};
    dispatch(fetchProductsByFilterAsync({filter,sort,pagination,admin:true}))

  }, [dispatch,filter,sort,page]);

  useEffect(() => {
    setpage(1);
  }, [totalItems, sort]);

  useEffect(() => {
    dispatch(fetchAllBrandsAsync());
    dispatch(fetchAllCategoriesAsync());
  }, []);

  return (
    <div>
      <div>

      <div className="bg-white">
      <div>
        {/* Mobile filter dialog */}
        <MobileFilter filters={filters} mobileFiltersOpen={mobileFiltersOpen} setMobileFiltersOpen={setMobileFiltersOpen} handleFilter={handleFilter}></MobileFilter>

        <main className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          <div className="flex items-baseline justify-between border-b border-gray-200 pb-6 pt-24">
            <div className='flex gap-5 items-center'>
              <h1 className="text-4xl font-bold tracking-tight text-gray-900">All Products</h1>
              <div className='flex justify-center px-3 py-1 hover:bg-green-500 items-center bg-green-600 mt-3 rounded-md text-white font-semibold text-[18px]'>
                  <Link to='/admin/product-form'>ADD NEW PRODUCT</Link>
              </div>
            </div>
            
            <div className="flex items-center">
              <Menu as="div" className="relative inline-block text-left">
                <div>
                  <MenuButton className="group inline-flex justify-center text-sm font-medium text-gray-700 hover:text-gray-900">
                    Sort
                    <ChevronDownIcon
                      className="-mr-1 ml-1 h-5 w-5 flex-shrink-0 text-gray-400 group-hover:text-gray-500"
                      aria-hidden="true"
                    />
                  </MenuButton>
                </div>

                <Transition
                  enter="transition ease-out duration-100"
                  enterFrom="transform opacity-0 scale-95"
                  enterTo="transform opacity-100 scale-100"
                  leave="transition ease-in duration-75"
                  leaveFrom="transform opacity-100 scale-100"
                  leaveTo="transform opacity-0 scale-95"
                >
                  <MenuItems className="absolute right-0 z-10 mt-2 w-40 origin-top-right rounded-md bg-white shadow-2xl ring-1 ring-black ring-opacity-5 focus:outline-none">
                    <div className="py-1">
                      {sortOptions.map((option) => (
                        <MenuItem key={option.name}>
                          {({ focus }) => (
                            <p
                            onClick={e=>handleSort(e,option)}
                              className={classNames(
                                option.current ? 'font-medium text-gray-900' : 'text-gray-500',
                                focus ? 'bg-gray-100' : '',
                                'block px-4 py-2 text-sm'
                              )}
                            >
                              {option.name}
                            </p>
                          )}
                        </MenuItem>
                      ))}
                    </div>
                  </MenuItems>
                </Transition>
              </Menu>

              <button type="button" className="-m-2 ml-5 p-2 text-gray-400 hover:text-gray-500 sm:ml-7">
                <span className="sr-only">View grid</span>
                <Squares2X2Icon className="h-5 w-5" aria-hidden="true" />
              </button>
              <button
                type="button"
                className="-m-2 ml-4 p-2 text-gray-400 hover:text-gray-500 sm:ml-6 lg:hidden"
                onClick={() => setMobileFiltersOpen(true)}
              >
                <span className="sr-only">Filters</span>
                <FunnelIcon className="h-5 w-5" aria-hidden="true" />
              </button>
            </div>
          </div>

          <section aria-labelledby="products-heading" className="pb-24 pt-6">
            <h2 id="products-heading" className="sr-only">
              Products
            </h2>

            <div className="grid grid-cols-1 gap-x-8 gap-y-10 lg:grid-cols-4">
              {/* Filters */}
              <DesktopFilter filters={filters} handleFilter={handleFilter}></DesktopFilter>

              {/* Product grid */}
              <div className="lg:col-span-3">
                <ProductGrid products={products}></ProductGrid>
              </div>

              {/* Product grid end */}


            
            </div>
          </section>

          {/* Section of product and filters end here */}
          
          <Pagination page={page} setpage={setpage} handlePage={handlePage} totalItems={totalItems}></Pagination>
          
        </main>
      </div>
    </div>
      </div>
    </div>    
  );
}


function MobileFilter({filters,mobileFiltersOpen,setMobileFiltersOpen,handleFilter}){
  return (
    <Transition show={mobileFiltersOpen}>
          <Dialog className="relative z-40 lg:hidden" onClose={setMobileFiltersOpen}>
            <TransitionChild
              enter="transition-opacity ease-linear duration-300"
              enterFrom="opacity-0"
              enterTo="opacity-100"
              leave="transition-opacity ease-linear duration-300"
              leaveFrom="opacity-100"
              leaveTo="opacity-0"
            >
              <div className="fixed inset-0 bg-black bg-opacity-25" />
            </TransitionChild>

            <div className="fixed inset-0 z-40 flex">
              <TransitionChild
                enter="transition ease-in-out duration-300 transform"
                enterFrom="translate-x-full"
                enterTo="translate-x-0"
                leave="transition ease-in-out duration-300 transform"
                leaveFrom="translate-x-0"
                leaveTo="translate-x-full"
              >
                <DialogPanel className="relative ml-auto flex h-full w-full max-w-xs flex-col overflow-y-auto bg-white py-4 pb-12 shadow-xl">
                  <div className="flex items-center justify-between px-4">
                    <h2 className="text-lg font-medium text-gray-900">Filters</h2>
                    <button
                      type="button"
                      className="-mr-2 flex h-10 w-10 items-center justify-center rounded-md bg-white p-2 text-gray-400"
                      onClick={() => setMobileFiltersOpen(false)}
                    >
                      <span className="sr-only">Close menu</span>
                      <XMarkIcon className="h-6 w-6" aria-hidden="true" />
                    </button>
                  </div>

                  {/* Filters */}
                  <form className="mt-4 border-t border-gray-200">

                    {filters.map((section) => (
                      <Disclosure as="div" key={section.id} className="border-t border-gray-200 px-4 py-6">
                        {({ open }) => (
                          <>
                            <h3 className="-mx-2 -my-3 flow-root">
                              <DisclosureButton className="flex w-full items-center justify-between bg-white px-2 py-3 text-gray-400 hover:text-gray-500">
                                <span className="font-medium text-gray-900">{section.name}</span>
                                <span className="ml-6 flex items-center">
                                  {open ? (
                                    <MinusIcon className="h-5 w-5" aria-hidden="true" />
                                  ) : (
                                    <PlusIcon className="h-5 w-5" aria-hidden="true" />
                                  )}
                                </span>
                              </DisclosureButton>
                            </h3>
                            <DisclosurePanel className="pt-6">
                              <div className="space-y-6">
                                {section.options.map((option, optionIdx) => (
                                  <div key={option.value} className="flex items-center">
                                    <input
                                      id={`filter-mobile-${section.id}-${optionIdx}`}
                                      name={`${section.id}[]`}
                                      defaultValue={option.value}
                                      type="checkbox"
                                      defaultChecked={option.checked}
                                      onChange={e=>handleFilter(e,section,option)}
                                      className="h-4 w-4 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                                    />
                                    <label
                                      htmlFor={`filter-mobile-${section.id}-${optionIdx}`}
                                      className="ml-3 min-w-0 flex-1 text-gray-500"
                                    >
                                      {option.label}
                                    </label>
                                  </div>
                                ))}
                              </div>
                            </DisclosurePanel>
                          </>
                        )}
                      </Disclosure>
                    ))}
                  </form>
                </DialogPanel>
              </TransitionChild>
            </div>
          </Dialog>
    </Transition>
  );
}

function DesktopFilter({filters,handleFilter}){
  return (
    <form className="hidden lg:block">

                {filters.map((section) => (
                  <Disclosure as="div" key={section.id} className="border-b border-gray-200 py-6">
                    {({ open }) => (
                      <>
                        <h3 className="-my-3 flow-root">
                          <DisclosureButton className="flex w-full items-center justify-between bg-white py-3 text-sm text-gray-400 hover:text-gray-500">
                            <span className="font-medium text-gray-900">{section.name}</span>
                            <span className="ml-6 flex items-center">
                              {open ? (
                                <MinusIcon className="h-5 w-5" aria-hidden="true" />
                              ) : (
                                <PlusIcon className="h-5 w-5" aria-hidden="true" />
                              )}
                            </span>
                          </DisclosureButton>
                        </h3>
                        <DisclosurePanel className="pt-6">
                          <div className="space-y-4">
                            {section.options.map((option, optionIdx) => (
                              <div key={optionIdx} className="flex items-center">
                                <input
                                  id={`filter-${section.id}-${optionIdx}`}
                                  name={`${section.id}[]`}
                                  defaultValue={option.value}
                                  type="checkbox"
                                  defaultChecked={option.checked}
                                  onChange={e=>handleFilter(e,section,option)}
                                  className="h-4 w-4 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                                />
                                <label
                                  htmlFor={`filter-${section.id}-${optionIdx}`}
                                  className="ml-3 text-sm text-gray-600"
                                >
                                  {option.label}
                                </label>
                              </div>
                            ))}
                          </div>
                        </DisclosurePanel>
                      </>
                    )}
                  </Disclosure>
                ))}
    </form>
  );
}

function Pagination({page,setpage,handlePage,totalItems=100}){
  const totalpages=Math.ceil(totalItems/ITEMS_PER_PAGE);
  return (
    <div className="flex items-center justify-between border-t border-gray-200 bg-white px-4 py-3 sm:px-6">
      <div className="flex flex-1 justify-between sm:hidden">
        <div
          onClick={e=>page>1 ? handlePage(page-1):handlePage(page)}
          className="relative inline-flex items-center cursor-pointer rounded-md border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
        >
          Previous
        </div>
        <div
          onClick={e=>page<totalpages ? handlePage(page+1):handlePage(page)}
          className="relative ml-3 inline-flex items-center cursor-pointer rounded-md border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
        >
          Next
        </div>
      </div>
      <div className="hidden sm:flex sm:flex-1 sm:items-center sm:justify-between">
        <div>
          <p className="text-sm text-gray-700">
            Showing <span className="font-medium">{((page-1)*ITEMS_PER_PAGE)+1}</span> to <span className="font-medium">{page*ITEMS_PER_PAGE>totalItems ? totalItems:page*ITEMS_PER_PAGE}</span> of{' '}
            <span className="font-medium">{totalItems}</span> results
          </p>
        </div>
        <div>
          <nav className="isolate inline-flex -space-x-px rounded-md shadow-sm" aria-label="Pagination">
            <div
              onClick={e=>page>1 ? handlePage(page-1):handlePage(page)}
              className="relative inline-flex cursor-pointer items-center rounded-l-md px-2 py-2 text-gray-400 ring-1 ring-inset ring-gray-300 hover:bg-gray-50 focus:z-20 focus:outline-offset-0"
            >
              <span className="sr-only">Previous</span>
              <ChevronLeftIcon className="h-5 w-5" aria-hidden="true" />
            </div>
            {/* Current: "z-10 bg-indigo-600 text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600", Default: "text-gray-900 ring-1 ring-inset ring-gray-300 hover:bg-gray-50 focus:outline-offset-0" */}
            
            {Array.from({length:totalpages}).map((e,index)=>
            
              <div
              onClick={e=>handlePage(index+1)}
              aria-current="page"
              key={index}
              className={`relative z-10 cursor-pointer border-gray-400 inline-flex items-center ${index+1===page? 'bg-indigo-600 text-white':'text-gray-400'}  px-4 py-2 text-sm font-semibold  focus:z-20 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600`}
              >
              {index+1}
              </div>

            
            )}

            <div
              onClick={e=>page<totalpages ? handlePage(page+1):handlePage(page)}
              className="relative inline-flex cursor-pointer items-center rounded-r-md px-2 py-2 text-gray-400 ring-1 ring-inset ring-gray-300 hover:bg-gray-50 focus:z-20 focus:outline-offset-0"
            >
              <span className="sr-only">Next</span>
              <ChevronRightIcon className="h-5 w-5" aria-hidden="true" />
            </div>
          </nav>
        </div>
      </div>
    </div>
  );
}

function ProductGrid({products}){
  return (
    <div className="bg-white">
      <div className="mx-auto max-w-2xl px-4 py-0 sm:px-6 sm:py-0 lg:max-w-7xl lg:px-8">

        <div className="mt-6 grid grid-cols-1 gap-x-6 gap-y-10 sm:grid-cols-2 lg:grid-cols-3 xl:gap-x-8">
          {products.map((product,index) => (
            <div key={index}>
              <Link to={`/product-details/${product.id}`} key={product.id}>
                <div key={product.id} className={`group relative ${product.stock===0 ? 'bg-red-200':'bg-sky-100'} rounded-md p-2`}>
                  <div className={`aspect-h-1 aspect-w-1 w-full overflow-hidden rounded-md bg-gray-200 lg:aspect-none lg:h-80 ${product.deleted? 'opacity-50 group-hover:opacity-50' : 'group-hover:opacity-75'}`}>
                    <img
                      src={product.thumbnail}
                      alt={product.imageAlt}
                      className="h-full w-full object-cover object-center lg:h-full lg:w-full"
                    />
                  </div>
                  <div className={`mt-4 flex justify-between ${product.deleted? 'opacity-20' : ''}`}>
                    <div>
                      <h3 className="text-sm text-gray-700">
                        <div href={product.href} className='font-semibold'>
                          <span aria-hidden="true" className="absolute inset-0" />
                          {product.title}
                        </div>
                      </h3>
                      <p className="mt-1 text-sm text-white bg-sky-800 w-max px-3 py-1 rounded-md font-medium"><StarIcon className='w-5 h-5 text-yellow-400 inline mr-1 align-bottom'></StarIcon> {parseFloat(product.rating.toFixed(1))}</p>
                    </div>
                    <div className="flex flex-col items-end gap-0.5 w-max">
                      <p className="text-sm font-medium text-gray-600 line-through">${product.price}</p>
                      <p className="text-lg font-medium text-gray-600">${discountedPrice(product)}</p>
                    </div>
                  </div>
                  {product.deleted && <div className='text-red-700 mt-4 font-semibold uppercase flex justify-center'>
                    <p>Product Deleted</p>
                  </div>}
                  {product.stock===0 && (
                  <div>
                    <p className='text-[15px] font-semibold uppercase text-red-600 mt-2 text-center'>Out of stock</p>
                  </div>
                  )}
                </div>
              </Link>
              <div className='flex justify-center hover:bg-indigo-500 items-center bg-indigo-600 mt-3 rounded-md text-white font-semibold text-[18px]'>
                <Link to={`/admin/product-form/edit/${product.id}`}>EDIT ITEM</Link>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}